package es.luisev.tareas.entity;
import jakarta.persistence.*;
import lombok.*;
import java.math.BigDecimal;
@Entity @Table(name="peticion") @Getter @Setter @NoArgsConstructor
public class Peticion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String codigo; @Column(nullable=false) private String asunto; private String descripcion; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="categoria_id") private Categoria categoria; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="subcategoria_id") private Subcategoria subcategoria; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="usuario_id") private Usuario usuario; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="estado_actual_id") private EstadoPeticion estadoActual; @Column(name="fecha_alta",nullable=false) private String fechaAlta; @Column(name="fecha_inicio_prevista") private String fechaInicioPrevista; @Column(name="fecha_fin_prevista") private String fechaFinPrevista; @Column(name="fecha_inicio_real") private String fechaInicioReal; @Column(name="fecha_fin_real") private String fechaFinReal; @Column(name="horas_previstas") private BigDecimal horasPrevistas; @Column(name="horas_reales",nullable=false) private BigDecimal horasReales; @Column(nullable=false) private BigDecimal porcentaje; @Column(name="ruta_documentos") private String rutaDocumentos; @Column(nullable=false) private boolean activo; }
